/bin/zsh -lc "node - <<'NODE'
const fs=require('fs'),crypto=require('crypto'),path=require('path');
for (const d of ['.planning/milestones/M002/reviews/evidence/cr313-frontend-implementation-submission-130','.planning/milestones/M002/reviews/evidence/cr313-backend-submission-129']) {
 const m=JSON.parse(fs.readFileSync(path.join(d,'delivery-manifest.json')));
 const key=m.frontend_files?'frontend_files':'backend_files';
 const files=[...(m[key]||[]),...(m.delivery_files||[])];
 let missing=[],bad=[];
 for(const x of files){ if("'!fs.existsSync(x.path)) missing.push(x.path); else if(x.sha256 && crypto.createHash('"'sha256').update(fs.readFileSync(x.path)).digest('hex')"'!==x.sha256) bad.push(x.path); }
 const archives=fs.readdirSync(d).filter(n=>/'"\\.tar\\.gz"'$|'"\\.zip"'$|archive/i.test(n));
 console.log(JSON.stringify({dir:d,version:m.version,source_files:(m[key]||[]).length,delivery_files:(m.delivery_files||[]).length,diff_files:m.frontend_diff?.files??m.backend_diff?.files,archives,missing,bad},null,2));
}
NODE
find .planning/milestones/M002/verification .planning/milestones/M002/handoffs -maxdepth 3 -type f | rg '"'config-portability|verification/(coverage-matrix|report|uat|ai-evaluation)|handoffs/(verification|config-portability)' | sort
rg -l 'CR313|M002-FI-CR313-01|config-portability' .planning/milestones/M002/verification .planning/milestones/M002/handoffs | sort
for f in .planning/milestones/M002/verification/config-portability-plan.md .planning/milestones/M002/verification/config-portability-matrix.md .planning/milestones/M002/verification/config-portability-report.md .planning/milestones/M002/verification/config-portability-uat.md .planning/milestones/M002/handoffs/config-portability-verification.md; do test -f \""'$f" && { echo "--- $f"; sed -n '"'1,260p' \""'$f"; }; done
rg -n '"'TRANSITION-M002-131' .planning/workflow/history.yaml || true
rg -n 'M002-UI-32|CR-313|status: open|status: awaiting_user_review' .planning/milestones/M002/changes/CR-313.md .planning/milestones/M002/handoffs/config-portability-frontend-implementation.md .planning/milestones/M002/continuation.md | sed -n '1,200p'"

